from collections import deque

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    bg=max(range(10), key=lambda c:sum(v==c for row in grid for v in row))
    seen=set()
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            # Rectangular frame components have complete perimeter of the component color.
            if r1-r0<2 or c1-c0<2: continue
            perimeter={(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                       if y in (r0,r1) or x in (c0,c1)}
            if set(comp)==perimeter:
                fill=color+1 if color%2==0 else color-1
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1): out[y][x]=fill
    return out

